/* isry.drmgs.stdnt.mapper.YouthLifeRecodeDetailMapper.UpdateYngbsInfo - 응용2팀 강화영  */

MERGE INTO
        AKA300      AA      
USING   DUAL
    ON
    (
            AA.CASE_MNG_NO       = #{CASE_MNG_NO} 
        AND AA.CASE_MNG_ODRNO    = #{CASE_MNG_ODRNO} 
    )
WHEN MATCHED THEN
    UPDATE SET
        AA.CNSTN_YN        = NVL(#{CNSTN_YN} , 'N')
    , AA.CNSTN_YR      = #{CNSTN_YR}
    , AA.DEL_YN        = 'N'
    , AA.LAST_MDFR_ID  = #{LAST_MDFR_ID}       
    , AA.LAST_MDFCN_DT = SYSDATE
WHEN NOT MATCHED THEN 
    INSERT
    (
        AA.CASE_MNG_NO
        , AA.CASE_MNG_ODRNO
        ,   AA.CNSTN_YN
        ,   AA.CNSTN_YR
        ,   AA.FRST_RGTR_ID
        ,   AA.FRST_REG_DT 
    )
    VALUES
    (
        #{CASE_MNG_NO}
        , #{CASE_MNG_ODRNO}
        ,    NVL(#{CNSTN_YN, jdbcType=VARCHAR} ,'N')
        ,   #{CNSTN_YR, jdbcType=VARCHAR}
        ,   #{LAST_MDFR_ID}
        ,   SYSDATE
    )


