FROM AKA340 /* 수상경력 */
WHERE 1=1 
  AND CASE_MNG_NO       =   #{CASE_MNG_NO, jdbcType=VARCHAR}  
  AND CASE_MNG_ODRNO    =   #{CASE_MNG_ODRNO, jdbcType=VARCHAR}  
