            AA.CASE_MNG_NO       = #{INDV_DSCSN_REQSTD_NO, jdbcType=VARCHAR} 
        AND AA.CASE_MNG_ODRNO    = #{CASE_MNG_ODRNO, jdbcType=VARCHAR} 
    )
WHEN MATCHED THEN
    UPDATE SET
        AA.ATFINO        = #{ATFINO} 
    , AA.CNSTN_YN = NVL(#{CNSTN_YN}, 'N')     
    , AA.LAST_MDFR_ID  = #{LAST_MDFR_ID}       
    , AA.LAST_MDFCN_DT = SYSDATE
WHEN NOT MATCHED THEN 
    INSERT
    (
            AA.ATFINO
        ,   AA.CNSTN_YN
        ,   AA.FRST_RGTR_ID
        ,   AA.FRST_REG_DT 
    )
    VALUES
    (
            #{ATFINO, jdbcType=VARCHAR} 
        ,   NVL(#{CNSTN_YN, jdbcType=VARCHAR}, 'N')  
        ,   #{LAST_MDFR_ID}
        ,   SYSDATE
    )

