   SET BGNG_YMD         = #{BGNG_YMD, jdbcType=VARCHAR}                    
      ,END_YMD          = #{END_YMD, jdbcType=VARCHAR}
WHERE CASE_MNG_NO       = #{INDV_DSCSN_REQSTD_NO, jdbcType=VARCHAR} 
  AND CASE_MNG_ODRNO    = #{CASE_MNG_ODRNO, jdbcType=VARCHAR}
  AND INDEX_SN          = #{INDEX_SN, jdbcType=VARCHAR}

